=== FILE: rtl/axil_timer.v ===
// axil_timer: AXI4-Lite timer peripheral with interrupt.
// Traces to requirement req-2b2b91a584 through microarchitecture_spec.md
// (sha256:1194efd1afa5f4acdbaf40a58155f361520cd5cb3198053ccb0bfedcca9ab62a)
// and interface_spec.md (sha256:d7eda57ee2f8e84ee593a0ddcb4f63b3402881dbc51e24e89ec73296d9be0c95).
// Not reviewed. No tool run backs this file.
`default_nettype none

module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output wire [1:0]            s_axil_bresp,
    output wire                  s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output wire [31:0]           s_axil_rdata,
    output wire [1:0]            s_axil_rresp,
    output wire                  s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  // ---------------------------------------------------------------
  // State registers (microarchitecture section 2)
  // ---------------------------------------------------------------
  reg                  aw_held_q;
  reg [ADDR_WIDTH-1:0] awaddr_q;
  reg                  w_held_q;
  reg [31:0]           wdata_q;
  reg [3:0]            wstrb_q;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [31:0]           rdata_q;
  reg                  en_q;
  reg                  ie_q;
  reg                  mode_q;
  reg [31:0]           load_q;
  reg [31:0]           count_q;
  reg                  expired_q;

  // Next-state values
  reg                  aw_held_d;
  reg [ADDR_WIDTH-1:0] awaddr_d;
  reg                  w_held_d;
  reg [31:0]           wdata_d;
  reg [3:0]            wstrb_d;
  reg                  bvalid_d;
  reg [1:0]            bresp_d;
  reg                  rvalid_d;
  reg [1:0]            rresp_d;
  reg [31:0]           rdata_d;
  reg                  en_d;
  reg                  ie_d;
  reg                  mode_d;
  reg [31:0]           load_d;
  reg [31:0]           count_d;
  reg                  expired_d;
  reg [31:0]           rd_mux;

  // ---------------------------------------------------------------
  // Readies and outputs (section 4.1): functions of flops only
  // ---------------------------------------------------------------
  assign s_axil_awready = ~aw_held_q & ~bvalid_q;
  assign s_axil_wready  = ~w_held_q & ~bvalid_q;
  assign s_axil_arready = ~rvalid_q;
  assign s_axil_bvalid  = bvalid_q;
  assign s_axil_bresp   = bresp_q;
  assign s_axil_rvalid  = rvalid_q;
  assign s_axil_rresp   = rresp_q;
  assign s_axil_rdata   = rdata_q;
  assign irq            = expired_q & ie_q;   // section 8

  // ---------------------------------------------------------------
  // Write path (section 5)
  // ---------------------------------------------------------------
  wire aw_fire     = s_axil_awvalid & s_axil_awready;
  wire w_fire      = s_axil_wvalid & s_axil_wready;
  wire wr_complete = (aw_fire | aw_held_q) & (w_fire | w_held_q);

  wire [ADDR_WIDTH-1:0] addr_e = aw_held_q ? awaddr_q : s_axil_awaddr;
  wire [31:0]           data_e = w_held_q ? wdata_q : s_axil_wdata;
  wire [3:0]            strb_e = w_held_q ? wstrb_q : s_axil_wstrb;

  // Decode (section 5.4): mapped only if aligned and below 0x10.
  // Supported ADDR_WIDTH is 4..8, so the 9-bit extension always pads.
  wire [8:0] waddr_x   = {{(9-ADDR_WIDTH){1'b0}}, addr_e};
  wire       wr_mapped = (waddr_x[1:0] == 2'b00) && (waddr_x[8:4] == 5'd0);
  wire [1:0] wr_idx    = waddr_x[3:2];
  wire       wr_err    = ~wr_mapped | (wr_idx == 2'd2);
  wire       wr_ctrl   = wr_complete & wr_mapped & (wr_idx == 2'd0) & strb_e[0];
  wire       wr_load   = wr_complete & wr_mapped & (wr_idx == 2'd1);
  wire       wr_sclr   = wr_complete & wr_mapped & (wr_idx == 2'd3) & strb_e[0] & data_e[0];

  // ---------------------------------------------------------------
  // Read path (section 6)
  // ---------------------------------------------------------------
  wire       ar_fire   = s_axil_arvalid & s_axil_arready;
  wire [8:0] raddr_x   = {{(9-ADDR_WIDTH){1'b0}}, s_axil_araddr};
  wire       rd_mapped = (raddr_x[1:0] == 2'b00) && (raddr_x[8:4] == 5'd0);
  wire [1:0] rd_idx    = raddr_x[3:2];

  // ---------------------------------------------------------------
  // Timer datapath (section 7)
  // ---------------------------------------------------------------
  wire        end_c     = en_q & ((count_q == 32'd0) | (count_q == 32'd1));
  wire [31:0] count_dec = count_q - 32'd1;

  // Holding registers (section 5.2)
  always @* begin
    aw_held_d = aw_held_q;
    awaddr_d  = awaddr_q;
    w_held_d  = w_held_q;
    wdata_d   = wdata_q;
    wstrb_d   = wstrb_q;
    if (wr_complete) begin
      aw_held_d = 1'b0;
      w_held_d  = 1'b0;
    end else begin
      if (aw_fire) begin
        aw_held_d = 1'b1;
        awaddr_d  = s_axil_awaddr;
      end
      if (w_fire) begin
        w_held_d = 1'b1;
        wdata_d  = s_axil_wdata;
        wstrb_d  = s_axil_wstrb;
      end
    end
  end

  // Write response (section 5.3)
  always @* begin
    bvalid_d = bvalid_q;
    bresp_d  = bresp_q;
    if (wr_complete) begin
      bvalid_d = 1'b1;
      bresp_d  = wr_err ? RESP_SLVERR : RESP_OKAY;
    end else if (s_axil_bready) begin
      bvalid_d = 1'b0;
    end
  end

  // Read mux: pre-edge register values (TMR-READ-VALUE)
  always @* begin
    case (rd_idx)
      2'd0:    rd_mux = {29'd0, mode_q, ie_q, en_q};
      2'd1:    rd_mux = load_q;
      2'd2:    rd_mux = count_q;
      2'd3:    rd_mux = {31'd0, expired_q};
      default: rd_mux = 32'd0;
    endcase
  end

  // Read response (section 6)
  always @* begin
    rvalid_d = rvalid_q;
    rresp_d  = rresp_q;
    rdata_d  = rdata_q;
    if (ar_fire) begin
      rvalid_d = 1'b1;
      if (rd_mapped) begin
        rresp_d = RESP_OKAY;
        rdata_d = rd_mux;
      end else begin
        rresp_d = RESP_SLVERR;
        rdata_d = 32'd0;
      end
    end else if (s_axil_rready) begin
      rvalid_d = 1'b0;
    end
  end

  // EN / IE / MODE / COUNT next state (section 7.2, first matching row wins)
  always @* begin
    en_d    = en_q;
    ie_d    = ie_q;
    mode_d  = mode_q;
    count_d = count_q;
    if (wr_ctrl) begin
      ie_d   = data_e[1];
      mode_d = data_e[2];
      if (data_e[0]) begin
        en_d    = 1'b1;              // start / restart (TMR-START, TMR-CTRL-WINS)
        count_d = load_q;
      end else begin
        en_d = 1'b0;
        if (end_c) begin
          count_d = mode_q ? load_q : 32'd0;   // TMR-CTRL-WINS, pre-edge MODE
        end else if (en_q) begin
          count_d = count_dec;                 // TMR-STOP-EDGE
        end
      end
    end else if (end_c) begin
      if (mode_q) begin
        count_d = load_q;            // periodic reload, old LOAD (section 7.3)
      end else begin
        en_d    = 1'b0;              // one-shot end (TMR-ONESHOT)
        count_d = 32'd0;
      end
    end else if (en_q) begin
      count_d = count_dec;
    end
  end

  // LOAD byte-wise write (TMR-LOAD)
  always @* begin
    load_d = load_q;
    if (wr_load) begin
      if (strb_e[0]) load_d[7:0]   = data_e[7:0];
      if (strb_e[1]) load_d[15:8]  = data_e[15:8];
      if (strb_e[2]) load_d[23:16] = data_e[23:16];
      if (strb_e[3]) load_d[31:24] = data_e[31:24];
    end
  end

  // EXPIRED: count end beats clear (TMR-END-BEATS-CLEAR)
  always @* begin
    if (end_c) begin
      expired_d = 1'b1;
    end else if (wr_sclr) begin
      expired_d = 1'b0;
    end else begin
      expired_d = expired_q;
    end
  end

  // ---------------------------------------------------------------
  // Register block: synchronous active-low reset, then q <= d
  // ---------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held_q <= 1'b0;
      awaddr_q  <= {ADDR_WIDTH{1'b0}};
      w_held_q  <= 1'b0;
      wdata_q   <= 32'd0;
      wstrb_q   <= 4'd0;
      bvalid_q  <= 1'b0;
      bresp_q   <= RESP_OKAY;
      rvalid_q  <= 1'b0;
      rresp_q   <= RESP_OKAY;
      rdata_q   <= 32'd0;
      en_q      <= 1'b0;
      ie_q      <= 1'b0;
      mode_q    <= 1'b0;
      load_q    <= 32'd0;
      count_q   <= 32'd0;
      expired_q <= 1'b0;
    end else begin
      aw_held_q <= aw_held_d;
      awaddr_q  <= awaddr_d;
      w_held_q  <= w_held_d;
      wdata_q   <= wdata_d;
      wstrb_q   <= wstrb_d;
      bvalid_q  <= bvalid_d;
      bresp_q   <= bresp_d;
      rvalid_q  <= rvalid_d;
      rresp_q   <= rresp_d;
      rdata_q   <= rdata_d;
      en_q      <= en_d;
      ie_q      <= ie_d;
      mode_q    <= mode_d;
      load_q    <= load_d;
      count_q   <= count_d;
      expired_q <= expired_d;
    end
  end

`ifdef FORMAL
  // Design-intent assertions (not run by this seat).
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  always @(*) begin
    if (!f_past_valid) assume(!aresetn);
  end

  always @(posedge aclk) begin
    if (f_past_valid) begin
      assert(!(aw_held_q && w_held_q));
      assert(!(aw_held_q && bvalid_q));
      assert(!(w_held_q && bvalid_q));
      assert(bresp_q == RESP_OKAY || bresp_q == RESP_SLVERR);
      assert(rresp_q == RESP_OKAY || rresp_q == RESP_SLVERR);
      if ($past(aresetn) && $past(bvalid_q) && !$past(s_axil_bready)) begin
        assert(bvalid_q);
        assert(bresp_q == $past(bresp_q));
      end
      if ($past(aresetn) && $past(rvalid_q) && !$past(s_axil_rready)) begin
        assert(rvalid_q);
        assert(rresp_q == $past(rresp_q));
        assert(rdata_q == $past(rdata_q));
      end
      if (!$past(aresetn)) begin
        assert(!bvalid_q && !rvalid_q && !aw_held_q && !w_held_q && !expired_q && !en_q);
      end
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: tb/tb_axil_timer.sv ===
// Self-checking testbench for axil_timer.
// Rules from interface_spec.md (sha256:d7eda57e...), traces to req-2b2b91a584.
// A cycle-level reference model is compared with every DUT output each cycle;
// directed tests add independent timing and value checks.
`default_nettype none

module tb_axil_timer;

  localparam integer AW  = 4;
  localparam integer TMO = 2000;
  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;
  localparam [AW-1:0] A_CTRL   = 4'h0;
  localparam [AW-1:0] A_LOAD   = 4'h4;
  localparam [AW-1:0] A_COUNT  = 4'h8;
  localparam [AW-1:0] A_STATUS = 4'hC;

  reg           clk     = 1'b0;
  reg           aresetn = 1'b0;
  reg  [AW-1:0] awaddr  = 4'h0;
  reg           awvalid = 1'b0;
  wire          awready;
  reg  [31:0]   wdata   = 32'd0;
  reg  [3:0]    wstrb   = 4'd0;
  reg           wvalid  = 1'b0;
  wire          wready;
  wire [1:0]    bresp;
  wire          bvalid;
  reg           bready  = 1'b0;
  reg  [AW-1:0] araddr  = 4'h0;
  reg           arvalid = 1'b0;
  wire          arready;
  wire [31:0]   rdata;
  wire [1:0]    rresp;
  wire          rvalid;
  reg           rready  = 1'b0;
  wire          irq;

  always #5 clk = ~clk;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
    .aclk(clk), .aresetn(aresetn),
    .s_axil_awaddr(awaddr), .s_axil_awvalid(awvalid), .s_axil_awready(awready),
    .s_axil_wdata(wdata), .s_axil_wstrb(wstrb), .s_axil_wvalid(wvalid), .s_axil_wready(wready),
    .s_axil_bresp(bresp), .s_axil_bvalid(bvalid), .s_axil_bready(bready),
    .s_axil_araddr(araddr), .s_axil_arvalid(arvalid), .s_axil_arready(arready),
    .s_axil_rdata(rdata), .s_axil_rresp(rresp), .s_axil_rvalid(rvalid), .s_axil_rready(rready),
    .irq(irq)
  );

  // ---------------------------------------------------------------
  // Bookkeeping
  // ---------------------------------------------------------------
  integer passed  = 0;
  integer failed  = 0;
  integer cyc     = 0;
  integer amb_old = 0;
  integer amb_new = 0;
  reg     done    = 1'b0;
  reg     chk_on  = 1'b0;

  task check;
    input            cond;
    input [8*64-1:0] msg;
    begin
      if (cond === 1'b1) begin
        passed = passed + 1;
      end else begin
        failed = failed + 1;
        $error("FAIL t=%0t cyc=%0d: %0s", $time, cyc, msg);
      end
    end
  endtask

  task finish_sim;
    reg [8*64-1:0] nonce;
    begin
      if (!done) begin
        done  = 1'b1;
        nonce = 0;
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
      end
    end
  endtask

  // ---------------------------------------------------------------
  // Background BREADY / RREADY driver (updated at posedge, stable at negedge)
  // bp_mode: 0 = always ready, 1 = pseudo-random, 2 = held low
  // ---------------------------------------------------------------
  reg [15:0] lfsr    = 16'hACE1;
  integer    bp_mode = 0;
  always @(posedge clk) begin
    lfsr <= {lfsr[14:0], lfsr[15] ^ lfsr[13] ^ lfsr[12] ^ lfsr[10]};
    case (bp_mode)
      0:       begin bready <= 1'b1;    rready <= 1'b1;    end
      1:       begin bready <= lfsr[0]; rready <= lfsr[5]; end
      default: begin bready <= 1'b0;    rready <= 1'b0;    end
    endcase
  end

  // ---------------------------------------------------------------
  // Reference model (interface_spec.md sections 3-9), updated at posedge
  // from the testbench-driven inputs and its own state only.
  // ---------------------------------------------------------------
  reg          m_aw_held = 1'b0, m_w_held = 1'b0, m_bvalid = 1'b0, m_rvalid = 1'b0;
  reg          m_en = 1'b0, m_ie = 1'b0, m_mode = 1'b0, m_expired = 1'b0, m_amb = 1'b0;
  reg [AW-1:0] m_awaddr = 4'h0;
  reg [31:0]   m_wdata = 32'd0;
  reg [3:0]    m_wstrb = 4'd0;
  reg [1:0]    m_bresp = 2'b00, m_rresp = 2'b00;
  reg [31:0]   m_rdata = 32'd0, m_load = 32'd0, m_count = 32'd0, m_alt = 32'd0;
  integer      m_ctrl_edge = 0;

  reg          n_aw_held, n_w_held, n_bvalid, n_rvalid, n_en, n_ie, n_mode, n_expired;
  reg [AW-1:0] n_awaddr;
  reg [31:0]   n_wdata, n_rdata, n_load, n_count;
  reg [3:0]    n_wstrb;
  reg [1:0]    n_bresp, n_rresp;
  reg          t_awf, t_wf, t_arf, t_cmp, t_map, t_ctrl, t_ld, t_clr, t_endc, t_amb;
  reg [AW-1:0] t_a;
  reg [31:0]   t_d;
  reg [3:0]    t_s;
  reg [1:0]    t_idx;
  integer      k;

  always @(posedge clk) begin
    cyc = cyc + 1;
    // TMR-LOAD-END-EDGE: accept either the old or the new LOAD as the reload.
    if (m_amb) begin
      if (dut.count_q === m_alt) begin
        m_count = m_alt;
        amb_new = amb_new + 1;
        check(1'b1, "TMR-LOAD-END-EDGE reload took new LOAD");
      end else begin
        amb_old = amb_old + 1;
        check(dut.count_q === m_count, "TMR-LOAD-END-EDGE COUNT is neither old nor new");
      end
      m_amb = 1'b0;
    end
    if (aresetn !== 1'b1) begin
      m_aw_held = 1'b0; m_w_held = 1'b0; m_awaddr = 4'h0; m_wdata = 32'd0; m_wstrb = 4'd0;
      m_bvalid = 1'b0; m_bresp = OKAY; m_rvalid = 1'b0; m_rresp = OKAY; m_rdata = 32'd0;
      m_en = 1'b0; m_ie = 1'b0; m_mode = 1'b0; m_load = 32'd0; m_count = 32'd0;
      m_expired = 1'b0; m_amb = 1'b0;
    end else begin
      t_awf = awvalid & ~m_aw_held & ~m_bvalid;
      t_wf  = wvalid & ~m_w_held & ~m_bvalid;
      t_arf = arvalid & ~m_rvalid;
      t_cmp = (t_awf | m_aw_held) & (t_wf | m_w_held);
      t_a   = m_aw_held ? m_awaddr : awaddr;
      t_d   = m_w_held ? m_wdata : wdata;
      t_s   = m_w_held ? m_wstrb : wstrb;
      t_map = (t_a[1:0] == 2'b00);          // AW = 4: every aligned offset is below 0x10
      t_idx = t_a[3:2];

      n_aw_held = m_aw_held; n_w_held = m_w_held; n_awaddr = m_awaddr;
      n_wdata = m_wdata; n_wstrb = m_wstrb; n_bvalid = m_bvalid; n_bresp = m_bresp;
      n_rvalid = m_rvalid; n_rresp = m_rresp; n_rdata = m_rdata;
      n_en = m_en; n_ie = m_ie; n_mode = m_mode; n_load = m_load; n_count = m_count;
      n_expired = m_expired;

      // R channel: pre-edge values
      if (t_arf) begin
        n_rvalid = 1'b1;
        if (araddr[1:0] == 2'b00) begin
          n_rresp = OKAY;
          case (araddr[3:2])
            2'd0:    n_rdata = {29'd0, m_mode, m_ie, m_en};
            2'd1:    n_rdata = m_load;
            2'd2:    n_rdata = m_count;
            default: n_rdata = {31'd0, m_expired};
          endcase
        end else begin
          n_rresp = SLVERR;
          n_rdata = 32'd0;
        end
      end else if (rready) begin
        n_rvalid = 1'b0;
      end

      // AW / W pairing
      if (t_cmp) begin
        n_aw_held = 1'b0;
        n_w_held  = 1'b0;
      end else begin
        if (t_awf) begin n_aw_held = 1'b1; n_awaddr = awaddr; end
        if (t_wf)  begin n_w_held = 1'b1; n_wdata = wdata; n_wstrb = wstrb; end
      end

      // B channel
      if (t_cmp) begin
        n_bvalid = 1'b1;
        n_bresp  = (!t_map || t_idx == 2'd2) ? SLVERR : OKAY;
      end else if (bready) begin
        n_bvalid = 1'b0;
      end

      t_ctrl = t_cmp & t_map & (t_idx == 2'd0) & t_s[0];
      t_ld   = t_cmp & t_map & (t_idx == 2'd1);
      t_clr  = t_cmp & t_map & (t_idx == 2'd3) & t_s[0] & t_d[0];
      t_endc = m_en & ((m_count == 32'd0) | (m_count == 32'd1));

      if (t_ld) begin
        for (k = 0; k < 4; k = k + 1)
          if (t_s[k]) n_load[8*k +: 8] = t_d[8*k +: 8];
      end

      if (t_ctrl) begin
        n_ie   = t_d[1];
        n_mode = t_d[2];
        if (t_d[0]) begin
          n_en    = 1'b1;
          n_count = m_load;
        end else begin
          n_en = 1'b0;
          if (t_endc)    n_count = m_mode ? m_load : 32'd0;
          else if (m_en) n_count = m_count - 32'd1;
        end
      end else if (t_endc) begin
        if (m_mode) begin
          n_count = m_load;
        end else begin
          n_en    = 1'b0;
          n_count = 32'd0;
        end
      end else if (m_en) begin
        n_count = m_count - 32'd1;
      end

      if (t_endc)     n_expired = 1'b1;
      else if (t_clr) n_expired = 1'b0;

      t_amb = t_endc & m_mode & ~t_ctrl & t_ld;
      if (t_ctrl) m_ctrl_edge = cyc;

      m_aw_held = n_aw_held; m_w_held = n_w_held; m_awaddr = n_awaddr;
      m_wdata = n_wdata; m_wstrb = n_wstrb; m_bvalid = n_bvalid; m_bresp = n_bresp;
      m_rvalid = n_rvalid; m_rresp = n_rresp; m_rdata = n_rdata;
      m_en = n_en; m_ie = n_ie; m_mode = n_mode; m_load = n_load; m_count = n_count;
      m_expired = n_expired;
      m_amb = t_amb;
      m_alt = n_load;
    end
  end

  // ---------------------------------------------------------------
  // Per-cycle comparison of every DUT output against the model
  // ---------------------------------------------------------------
  always @(negedge clk) begin
    if (chk_on) begin
      check(awready === (~m_aw_held & ~m_bvalid), "awready (TMR-READY)");
      check(wready  === (~m_w_held & ~m_bvalid),  "wready (TMR-READY)");
      check(arready === ~m_rvalid,                "arready (TMR-READY)");
      check(bvalid  === m_bvalid,                 "bvalid timing (TMR-RESPONSE-EDGE)");
      if (m_bvalid) check(bresp === m_bresp,      "bresp code / stability");
      check(rvalid  === m_rvalid,                 "rvalid timing (TMR-RESPONSE-EDGE)");
      if (m_rvalid) begin
        check(rresp === m_rresp, "rresp code / stability");
        check(rdata === m_rdata, "rdata value / stability (TMR-READ-VALUE)");
      end
      check(irq === (m_expired & m_ie), "irq = EXPIRED & IE (TMR-IRQ)");
    end
  end

  // ---------------------------------------------------------------
  // Bus tasks (called at a negedge, return at a negedge)
  // ---------------------------------------------------------------
  task do_write;
    input  [AW-1:0] a;
    input  [31:0]   d;
    input  [3:0]    s;
    input  integer  awd;
    input  integer  wd;
    input           wait_b;
    output [1:0]    resp;
    integer t;
    reg awdone, wdone, awhs, whs, bhs;
    begin
      awdone = 1'b0; wdone = 1'b0; t = 0; resp = 2'b11;
      while (!(awdone && wdone) && t < TMO) begin
        awvalid = ~awdone & (t >= awd);
        awaddr  = a;
        wvalid  = ~wdone & (t >= wd);
        wdata   = d;
        wstrb   = s;
        awhs = awvalid & awready;
        whs  = wvalid & wready;
        @(posedge clk);
        if (awhs) awdone = 1'b1;
        if (whs)  wdone  = 1'b1;
        @(negedge clk);
        t = t + 1;
      end
      awvalid = 1'b0;
      wvalid  = 1'b0;
      check(awdone & wdone, "AW/W handshake within timeout");
      if (awdone && wdone && wait_b) begin
        bhs = 1'b0; t = 0;
        while (!bhs && t < TMO) begin
          bhs  = bvalid & bready;
          resp = bresp;
          @(posedge clk);
          @(negedge clk);
          t = t + 1;
        end
        check(bhs, "B handshake within timeout");
      end
    end
  endtask

  task do_read;
    input  [AW-1:0] a;
    input  integer  ard;
    output [31:0]   d;
    output [1:0]    resp;
    integer t;
    reg ardone, arhs, rhs;
    begin
      ardone = 1'b0; t = 0; d = 32'd0; resp = 2'b11;
      while (!ardone && t < TMO) begin
        arvalid = (t >= ard);
        araddr  = a;
        arhs    = arvalid & arready;
        @(posedge clk);
        if (arhs) ardone = 1'b1;
        @(negedge clk);
        t = t + 1;
      end
      arvalid = 1'b0;
      check(ardone, "AR handshake within timeout");
      if (ardone) begin
        rhs = 1'b0; t = 0;
        while (!rhs && t < TMO) begin
          rhs  = rvalid & rready;
          d    = rdata;
          resp = rresp;
          @(posedge clk);
          @(negedge clk);
          t = t + 1;
        end
        check(rhs, "R handshake within timeout");
      end
    end
  endtask

  reg [1:0]  r_resp;
  reg [31:0] r_data;

  task wr;
    input [AW-1:0] a;
    input [31:0]   d;
    input [1:0]    exp_resp;
    begin
      do_write(a, d, 4'hF, 0, 0, 1'b1, r_resp);
      if (r_resp !== exp_resp) $display("  wr addr=%h data=%h resp=%b exp=%b", a, d, r_resp, exp_resp);
      check(r_resp === exp_resp, "directed write response code");
    end
  endtask

  task rd;
    input [AW-1:0] a;
    input [31:0]   exp_d;
    input [1:0]    exp_resp;
    begin
      do_read(a, 0, r_data, r_resp);
      if (r_data !== exp_d || r_resp !== exp_resp)
        $display("  rd addr=%h got %h/%b exp %h/%b", a, r_data, r_resp, exp_d, exp_resp);
      check(r_data === exp_d, "directed read data");
      check(r_resp === exp_resp, "directed read response code");
    end
  endtask

  task wait_irq;
    output integer at;
    integer t;
    begin
      t = 0;
      while (irq !== 1'b1 && t < TMO) begin
        @(negedge clk);
        t = t + 1;
      end
      check(irq === 1'b1, "irq raised within timeout");
      at = cyc;
    end
  endtask

  // Wait until the next edge is a count-end edge with COUNT == 1 before it.
  task wait_count1;
    integer t;
    begin
      t = 0;
      while (!(m_en && m_count == 32'd1) && t < TMO) begin
        @(negedge clk);
        t = t + 1;
      end
      check(m_en && m_count == 32'd1, "reached COUNT==1 for same-edge test");
      check(awready & wready, "bus idle at same-edge alignment");
    end
  endtask

  // ---------------------------------------------------------------
  // Directed sequence
  // ---------------------------------------------------------------
  integer    e0, t1, t2, t3, s_e, p_e, i;
  reg [1:0]  c_resp, c_resp2, c_rresp;
  reg [31:0] c_data, v1, iv;
  reg [AW-1:0] ra;

  initial begin
    repeat (3) @(posedge clk);
    @(negedge clk);
    aresetn = 1'b1;
    chk_on  = 1'b1;

    // 1. Reset values (TMR-RESET, TMR-MAP)
    rd(A_CTRL,   32'd0, OKAY);
    rd(A_LOAD,   32'd0, OKAY);
    rd(A_COUNT,  32'd0, OKAY);
    rd(A_STATUS, 32'd0, OKAY);

    // 2. LOAD writes: orders and strobes (TMR-ORDER, TMR-LOAD)
    wr(A_LOAD, 32'h12345678, OKAY);
    rd(A_LOAD, 32'h12345678, OKAY);
    do_write(A_LOAD, 32'hAABBCCDD, 4'b0101, 0, 3, 1'b1, r_resp);   // AW first
    check(r_resp === OKAY, "AW-first write OKAY");
    rd(A_LOAD, 32'h12BB56DD, OKAY);
    do_write(A_LOAD, 32'h00000000, 4'b1000, 4, 0, 1'b1, r_resp);   // W first
    check(r_resp === OKAY, "W-first write OKAY");
    rd(A_LOAD, 32'h00BB56DD, OKAY);
    do_write(A_LOAD, 32'hFFFFFFFF, 4'b0000, 0, 0, 1'b1, r_resp);   // empty strobe
    check(r_resp === OKAY, "empty-strobe write OKAY");
    rd(A_LOAD, 32'h00BB56DD, OKAY);

    // 3. Errors (TMR-SLVERR, TMR-DECODE)
    wr(A_COUNT, 32'h00000055, SLVERR);
    rd(A_COUNT, 32'd0, OKAY);
    wr(4'h2, 32'h1, SLVERR);
    wr(4'h5, 32'hFFFFFFFF, SLVERR);
    rd(A_LOAD, 32'h00BB56DD, OKAY);
    rd(4'h6, 32'd0, SLVERR);
    rd(4'h1, 32'd0, SLVERR);
    do_write(A_CTRL, 32'h7, 4'b1110, 0, 0, 1'b1, r_resp);          // no wstrb[0]
    check(r_resp === OKAY, "CTRL write without wstrb[0] OKAY");
    rd(A_CTRL, 32'd0, OKAY);

    // 4. One-shot length N=5 (TMR-COUNT-LENGTH, TMR-ONESHOT, TMR-IRQ)
    wr(A_LOAD, 32'd5, OKAY);
    wr(A_CTRL, 32'h3, OKAY);
    e0 = m_ctrl_edge;
    wait_irq(t1);
    check(t1 - e0 == 5, "one-shot ends on E+N");
    rd(A_CTRL,   32'h2, OKAY);
    rd(A_COUNT,  32'd0, OKAY);
    rd(A_STATUS, 32'h1, OKAY);
    wr(A_STATUS, 32'h0, OKAY);
    rd(A_STATUS, 32'h1, OKAY);
    do_write(A_STATUS, 32'h1, 4'b0010, 0, 0, 1'b1, r_resp);
    rd(A_STATUS, 32'h1, OKAY);
    wr(A_STATUS, 32'h1, OKAY);
    rd(A_STATUS, 32'h0, OKAY);
    check(irq === 1'b0, "irq low after STATUS clear");

    // 5. Periodic N=10 (TMR-PERIODIC)
    wr(A_LOAD, 32'd10, OKAY);
    wr(A_CTRL, 32'h7, OKAY);
    e0 = m_ctrl_edge;
    wait_irq(t1);
    check(t1 - e0 == 10, "periodic first end on E+N");
    wr(A_STATUS, 32'h1, OKAY);
    wait_irq(t2);
    check(t2 - e0 == 20, "periodic second end on E+2N");
    wr(A_STATUS, 32'h1, OKAY);
    wait_irq(t3);
    check(t3 - e0 == 30, "periodic third end on E+3N");
    rd(A_CTRL, 32'h7, OKAY);
    wr(A_CTRL, 32'h0, OKAY);
    wr(A_STATUS, 32'h1, OKAY);

    // 6. Stop edge still decrements, then COUNT holds (TMR-STOP, TMR-STOP-EDGE)
    wr(A_LOAD, 32'd100, OKAY);
    wr(A_CTRL, 32'h1, OKAY);
    s_e = m_ctrl_edge;
    repeat (10) @(negedge clk);
    wr(A_CTRL, 32'h0, OKAY);
    p_e = m_ctrl_edge;
    do_read(A_COUNT, 0, v1, r_resp);
    check(v1 == 32'd100 - (p_e - s_e), "COUNT after stop edge = N - (stop - start)");
    repeat (5) @(negedge clk);
    rd(A_COUNT, v1, OKAY);
    wr(A_CTRL, 32'h0, OKAY);
    rd(A_COUNT, v1, OKAY);

    // 7. Same-edge priorities (section 7.1)
    // a) end + CTRL EN=1
    wr(A_LOAD, 32'd8, OKAY);
    wr(A_CTRL, 32'h1, OKAY);
    wait_count1;
    do_write(A_CTRL, 32'h5, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_STATUS, 32'h1, OKAY);
    rd(A_CTRL,   32'h5, OKAY);
    // b) end + CTRL EN=0 with pre-edge MODE=1 -> COUNT <= LOAD
    wait_count1;
    do_write(A_CTRL, 32'h0, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_COUNT,  32'd8, OKAY);
    rd(A_STATUS, 32'h1, OKAY);
    rd(A_CTRL,   32'h0, OKAY);
    // c) end + CTRL EN=0 with pre-edge MODE=0 -> COUNT <= 0
    wr(A_STATUS, 32'h1, OKAY);
    wr(A_CTRL, 32'h1, OKAY);
    wait_count1;
    do_write(A_CTRL, 32'h0, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_COUNT,  32'd0, OKAY);
    rd(A_STATUS, 32'h1, OKAY);
    rd(A_CTRL,   32'h0, OKAY);
    // d) end + STATUS clear: end wins (periodic, then one-shot)
    wr(A_STATUS, 32'h1, OKAY);
    wr(A_CTRL, 32'h5, OKAY);
    wait_count1;
    do_write(A_STATUS, 32'h1, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_STATUS, 32'h1, OKAY);
    wr(A_CTRL, 32'h0, OKAY);
    wr(A_STATUS, 32'h1, OKAY);
    wr(A_CTRL, 32'h1, OKAY);
    wait_count1;
    do_write(A_STATUS, 32'h1, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_STATUS, 32'h1, OKAY);
    rd(A_CTRL,   32'h0, OKAY);
    // e) periodic end + LOAD write: old or new LOAD accepted (TMR-LOAD-END-EDGE)
    wr(A_STATUS, 32'h1, OKAY);
    wr(A_LOAD, 32'd6, OKAY);
    wr(A_CTRL, 32'h5, OKAY);
    wait_count1;
    do_write(A_LOAD, 32'd20, 4'hF, 0, 0, 1'b1, r_resp);
    rd(A_LOAD, 32'd20, OKAY);
    for (i = 0; i < 6; i = i + 1) begin
      repeat (4) @(negedge clk);
      do_read(A_COUNT, 0, c_data, c_rresp);
    end
    check(amb_old + amb_new == 1, "TMR-LOAD-END-EDGE coincidence exercised once");
    $display("  TMR-LOAD-END-EDGE outcome: old=%0d new=%0d", amb_old, amb_new);
    wr(A_CTRL, 32'h0, OKAY);
    wr(A_STATUS, 32'h1, OKAY);

    // 8. LOAD = 0 (TMR-LOAD-ZERO, TMR-LOAD-ZERO-PERIODIC)
    wr(A_LOAD, 32'd0, OKAY);
    wr(A_CTRL, 32'h3, OKAY);
    e0 = m_ctrl_edge;
    wait_irq(t1);
    check(t1 - e0 == 1, "LOAD=0 one-shot ends on E+1");
    rd(A_CTRL,  32'h2, OKAY);
    rd(A_COUNT, 32'd0, OKAY);
    wr(A_STATUS, 32'h1, OKAY);
    wr(A_CTRL, 32'h7, OKAY);
    wr(A_STATUS, 32'h1, OKAY);
    rd(A_STATUS, 32'h1, OKAY);
    rd(A_COUNT,  32'd0, OKAY);
    rd(A_CTRL,   32'h7, OKAY);
    wr(A_CTRL, 32'h0, OKAY);

    // 9. IE gating (TMR-IRQ-EDGE): EXPIRED is 1 here
    rd(A_STATUS, 32'h1, OKAY);
    check(irq === 1'b0, "irq low with IE=0");
    wr(A_CTRL, 32'h2, OKAY);
    check(irq === 1'b1, "irq high after IE=1 while EXPIRED");
    wr(A_CTRL, 32'h0, OKAY);
    check(irq === 1'b0, "irq low after IE=0");
    wr(A_STATUS, 32'h1, OKAY);

    // 10. Read and write accepted on the same edge (TMR-READ-VALUE)
    wr(A_LOAD, 32'h11, OKAY);
    fork
      do_write(A_LOAD, 32'h22, 4'hF, 0, 0, 1'b1, c_resp);
      do_read(A_LOAD, 0, c_data, c_rresp);
    join
    check(c_data === 32'h11, "same-edge read returns pre-edge LOAD");
    check(c_resp === OKAY, "same-edge write OKAY");
    rd(A_LOAD, 32'h22, OKAY);
    wr(A_LOAD, 32'd40, OKAY);
    wr(A_CTRL, 32'h5, OKAY);
    repeat (7) @(negedge clk);
    fork
      do_write(A_CTRL, 32'h5, 4'hF, 0, 0, 1'b1, c_resp);
      do_read(A_COUNT, 0, c_data, c_rresp);
    join
    wr(A_CTRL, 32'h0, OKAY);
    wr(A_STATUS, 32'h1, OKAY);

    // 11. Back-pressure: B stalled, next write must not be accepted
    bp_mode = 2;
    @(negedge clk);
    fork
      begin
        do_write(A_LOAD, 32'hA5A5A5A5, 4'hF, 0, 0, 1'b0, c_resp);
        do_write(A_LOAD, 32'h5A5A5A5A, 4'hF, 0, 0, 1'b1, c_resp2);
      end
      begin
        repeat (8) @(negedge clk);
        bp_mode = 0;
      end
    join
    check(c_resp2 === OKAY, "second write after B stall OKAY");
    rd(A_LOAD, 32'h5A5A5A5A, OKAY);

    //     R stalled while COUNT keeps changing (TMR-RESPONSE-RDATA-STABLE)
    wr(A_LOAD, 32'd1000, OKAY);
    wr(A_CTRL, 32'h1, OKAY);
    bp_mode = 2;
    @(negedge clk);
    fork
      do_read(A_COUNT, 0, c_data, c_rresp);
      begin
        repeat (10) @(negedge clk);
        bp_mode = 0;
      end
    join
    check(c_rresp === OKAY, "stalled COUNT read OKAY");
    wr(A_CTRL, 32'h0, OKAY);

    //     Random back-pressure with mixed traffic, timer running
    wr(A_LOAD, 32'd37, OKAY);
    wr(A_CTRL, 32'h7, OKAY);
    bp_mode = 1;
    for (i = 0; i < 24; i = i + 1) begin
      iv = i;
      case (i % 5)
        0: ra = A_LOAD;
        1: ra = A_COUNT;
        2: ra = A_STATUS;
        3: ra = 4'h6;
        default: ra = A_LOAD;
      endcase
      do_write(ra, iv * 32'h01010101, iv[3:0], i % 3, (i / 3) % 3, iv[0], c_resp);
      do_read(iv[3:0], i % 2, c_data, c_rresp);
    end
    do_write(A_CTRL, 32'h0, 4'hF, 0, 0, 1'b1, c_resp);
    bp_mode = 0;
    repeat (2) @(negedge clk);

    // 12. Reset during traffic: held AW discarded (TMR-RESET-EDGE)
    wr(A_LOAD, 32'd50, OKAY);
    wr(A_CTRL, 32'h3, OKAY);
    awvalid = 1'b1;
    awaddr  = A_CTRL;
    check(awready === 1'b1, "awready before held-AW reset test");
    @(posedge clk);
    @(negedge clk);
    awvalid = 1'b0;
    check(awready === 1'b0 && wready === 1'b1, "AW held without W");
    aresetn = 1'b0;
    @(posedge clk);
    @(negedge clk);
    aresetn = 1'b1;
    check(awready === 1'b1 && wready === 1'b1 && bvalid === 1'b0 && rvalid === 1'b0 && irq === 1'b0,
          "idle bus after reset edge");
    rd(A_CTRL,   32'd0, OKAY);
    rd(A_LOAD,   32'd0, OKAY);
    rd(A_COUNT,  32'd0, OKAY);
    rd(A_STATUS, 32'd0, OKAY);
    do_write(A_LOAD, 32'd3, 4'hF, 3, 0, 1'b1, r_resp);
    check(r_resp === OKAY, "write after reset OKAY");
    rd(A_LOAD, 32'd3, OKAY);
    rd(A_CTRL, 32'd0, OKAY);

    repeat (3) @(negedge clk);
    check(passed > 0, "at least one check passed");
    finish_sim;
  end

  initial begin
    #500000;
    check(1'b0, "global watchdog expired");
    finish_sim;
  end

endmodule

`default_nettype wire
